def P(body,members='',top=''):
    return "import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n"+members+"\n    public static void main(String[] args) throws Exception {\n"+body+"\n    }\n}\n"+top
topic('Strings & Basics')
M('b','k',"Which method signature is the standard entry point of a Java program?","public static void main(String[] args)","public void main(String args)","static void start(String[] args)","public static int main()","The JVM looks for a public static void method named main that takes a String array.")
M('b','k',"Which keyword creates a new object?","new","create","make","alloc","new allocates the object and calls its constructor.")
JV('b','o',"What does this program print?",P('        System.out.println(7 / 2);'),"3","3.5","4","2","Both operands are int, so the division is an integer division.")
JV('b','o',"What does this program print?",P('        String s = "Java";\n        System.out.println(s.length());'),"4","3","5","Java","length() returns the number of characters.")
JV('b','o',"What does this program print?",P('        System.out.println("5" + 3);'),"53","8","5 3","Error","When one operand of + is a String, the other is converted and the two are concatenated.")
JV('b','o',"What does this program print?",P('        System.out.println(5 + 3 + "x");'),"8x","53x","x8","5 3x","The expression is evaluated left to right. 5 + 3 is added first to give 8, then 'x' is appended.")
JV('b','o',"What does this program print?",P("        System.out.println('a' + 1);"),"98","a1","b","Error","A char is promoted to int in arithmetic. 'a' is 97, so the result is the int 98.")
JV('b','o',"What does this program print?",P("        char c = 'a';\n        c++;\n        System.out.println(c);"),"b","98","a1","Error","Incrementing a char moves to the next character code, so 'a' becomes 'b'.")
JV('b','o',"What does this program print?",P('        System.out.println(10 == 10.0);'),"true","false","Error","10","The int is promoted to double before the comparison, so the values are equal.")
M('b','k',"Which of these is NOT a primitive type in Java?","String","int","boolean","char","String is a class. The eight primitives are byte, short, int, long, float, double, char and boolean.")
M('b','k',"Which keyword is used to inherit from a class?","extends","implements","inherits","super","A class extends another class and implements interfaces.")
M('b','k',"Which package is imported automatically in every Java file?","java.lang","java.util","java.io","java.base","java.lang contains String, Math, System and other core classes.")
