JV('b','o',"What does this program print?",P('        int[] a = new int[3];\n        System.out.println(a.length + " " + a[0]);'),"3 0","3 null","2 0","0 0","Array elements default to 0 for int. length is a field, not a method.")
topic('Strings & Basics')
JV('i','o',"What does this program print?",P('        String a = "hi";\n        String b = new String("hi");\n        System.out.println((a == b) + " " + a.equals(b));'),"false true","true true","true false","false false","== compares references, and new String creates a separate object. equals compares the text.")
JV('i','o',"What does this program print?",P('        Integer x = 127, y = 127, p = 128, q = 128;\n        System.out.println((x == y) + " " + (p == q));'),"true false","true true","false false","false true","Integer values from -128 to 127 are cached, so == works there. Outside that range separate objects are created.")
JV('i','o',"What does this program print?",P('        String s = "a";\n        s.concat("b");\n        System.out.println(s);'),"a","ab","b","null","Strings are immutable. concat returns a new string, which was thrown away here.")
topic('Collections & Generics')
JV('i','o',"What does this program print?",P('        List<Integer> l = new ArrayList<>(List.of(10, 20, 30));\n        l.remove(1);\n        System.out.println(l);'),"[10, 30]","[20, 30]","[10, 20]","[10, 20, 30]","With an int argument, remove(int index) is chosen, so the element at index 1 (20) is removed. remove(Integer.valueOf(1)) would remove by value.")
